SIGS = [(b"%PDF", "pdf"), (b"PK\x03\x04", "zip"), (b"\x89PNG", "png")]
def detect(head):
    for sig, name in SIGS:
        if head.startswith(sig): return name
    return "unknown"
for h in [b"%PDF-1.7...", b"\x89PNG....", b"hello"]:
    print(repr(h[:6]), "->", detect(h))

