def parse_txt(b): return {"text": b.decode(errors="replace")}
def parse_csv(b):
    rows = [l.split(",") for l in b.decode().splitlines()]
    return {"headers": rows[0], "rows": rows[1:]}
REGISTRY = {"txt": parse_txt, "csv": parse_csv}
