def fallback(blob):
    printable = "".join(chr(b) if 32 <= b < 127 else "." for b in blob[:32])
    return {"bytes": len(blob), "head_ascii": printable, "parsed": False}
print(fallback(b"\x00\x01hello-world\xff\xfe"))

